cd /opt/kv-seed && python3 - <<'EOF'
import kvdump, json, time
old = kvdump.dump_server(6379)
new = kvdump.dump_server(6380)
print("old dbs:", {d: len(v) for d, v in old.items()})
print("new dbs:", {d: len(v) for d, v in new.items()})
print("digest old:", kvdump.digest(old))
print("digest new:", kvdump.digest(new))
print("digests equal:", kvdump.digest(old) == kvdump.digest(new))

# deep comparison including TTL within tolerance
tol = 1500  # ms
problems = []
if set(old) != set(new):
    problems.append(f"db sets differ: {set(old)} vs {set(new)}")
for db in old:
    o, n = old[db], new.get(db, {})
    if set(o) != set(n):
        problems.append(f"db{db} key sets differ: missing={set(o)-set(n)} extra={set(n)-set(o)}")
    for k in set(o) & set(n):
        ot, ov, op = o[k]; nt, nv, np_ = n[k]
        if ot != nt: problems.append(f"db{db} {k}: type {ot}!={nt}")
        if ov != nv: problems.append(f"db{db} {k} ({ot}): value differs")
        oexp, nexp = op > 0, np_ > 0
        if oexp != nexp: problems.append(f"db{db} {k}: expiry presence {op} vs {np_}")
        elif oexp and abs(op - np_) > tol: problems.append(f"db{db} {k}: ttl {op} vs {np_}")
print("problems:", len(problems))
for p in problems[:20]: print(" -", p)
EOF
